{
  "$schema": "./node_modules/@biomejs/biome/configuration_schema.json",
  "extends": [
    "ultracite/biome/core",
    "ultracite/biome/react",
    "ultracite/biome/next"
  ],
  "javascript": {
    "globals": ["Liveblocks"]
  },
  "files": {
    "includes": [
      "**/*",
      "!packages/design-system/components/ui",
      // Vendored from the AI Elements registry, same as components/ui above.
      // The two files we patched carry a comment explaining why.
      "!packages/design-system/components/ai-elements",
      "!packages/design-system/lib",
      "!packages/design-system/hooks",
      "!packages/collaboration/config.ts",
      "!docs/components/ui",
      "!docs/lib",
      "!docs/hooks",
      "!apps/docs/**/*.json",
      "!apps/email/.react-email",
      "!**/*.generated.*",
      "!**/*.svg"
    ]
  }
}
