import { generateToken } from "@/lib/token";

const TOKEN_EXPIRY_MS = 1000 * 60 * 60 * 24;

// Vague messaging for disposable/undeliverable to avoid revealing rejection reason
const VALIDATION_MESSAGES: Record<ValidationFailureReason, string> = {
  disposable:
    "This email address doesn't look quite right. Mind trying another one?",
  invalid_format: "Invalid email address provided",
  undeliverable:
    "This email address doesn't look quite right. Mind trying another one?",
};

export async function POST(request: NextRequest) {
  try {
    const res = await request.json();
    const email = res.email;

    const validation = await validateEmail(email);

    if (!validation.valid) {
      return NextResponse.json(
        {
          error: {
            message: VALIDATION_MESSAGES[validation.reason],
            name: "ValidationError",
          },
        },
        { status: 400 }
      );
    }

    const { token, hash } = generateToken();

    await database.subscriber.updateOne(
      { email },
      {
        $set: {
          token: hash,
          tokenExpiresAt: new Date(Date.now() + TOKEN_EXPIRY_MS),
        },
        $setOnInsert: {
          _id: createId(),
          createdAt: new Date(),
          emailVerified: null,
          image: null,
          name: null,
          role: "user",
        },
      },
      { upsert: true }
    );

    const { error } = await resend.emails.send({
      from: env.RESEND_FROM,
      react: ConfirmSubscription({
        baseUrl: new URL(request.url).origin,
        token,
      }),
      subject: "Important: Confirm your subscription",
      to: [email],
    });

    if (error) {
      log.error(`Failed to send confirmation email: ${JSON.stringify(error)}`);
      return NextResponse.json(
        {
          error: {
            message: "Failed to send confirmation email",
            name: "EmailError",
          },
        },
        { status: 500 }
      );
    }

    return NextResponse.json({
      message: "Confirm your subscription.",
    });
  } catch (error) {
    if (error instanceof SyntaxError) {
      return NextResponse.json(
        {
          error: { message: "Invalid request body", name: "ValidationError" },
        },
        { status: 400 }
      );
    }
    after(() => parseError(error));
    return NextResponse.json(
      {
        error: { message: "An unexpected error occurred", name: "ServerError" },
      },
      { status: 500 }
    );
  }
}

import { render } from "@react-email/render";
import { DigestEmail } from "@repo/email/templates/digest";
import { MongoClient, ObjectId } from "mongodb";

const MONGODB_URI = process.env.MONGODB_URI;
if (!MONGODB_URI) {
  console.error("MONGODB_URI environment variable is required");
  process.exit(1);
}

const client = new MongoClient(MONGODB_URI);
// MONGODB_URI has no database path, so the driver would otherwise default to
// "test". @repo/database and apps/web both read/write "app" — this CLI must
// agree or it silently operates on an empty, disconnected database.
const db = client.db(process.env.MONGODB_DB ?? "app");
const digests = db.collection("digests");

const [, , command, ...args] = process.argv;

async function handleCreate() {
  const title = args[0] || "Untitled Draft";
  const result = await digests.insertOne({
    content: "",
    createdAt: new Date(),
    misconception: "",
    scheduledFor: null,
    sentAt: null,
    status: "draft",
    title,
    updatedAt: new Date(),
  });
  console.log(`Created digest: ${result.insertedId}`);
}

function parseUpdateFlags(): Record<string, unknown> {
  const updates: Record<string, unknown> = { updatedAt: new Date() };
  for (let i = 1; i < args.length; i += 2) {
    const flag = args[i];
    const value = args[i + 1];
    switch (flag) {
      case "--title":
        updates.title = value;
        break;
      case "--misconception":
        updates.misconception = value;
        break;
      case "--content":
        updates.content = value;
        break;
      case "--series-name":
        updates["series.name"] = value;
        break;
      case "--series-part":
        updates["series.part"] = Number.parseInt(value, 10);
        break;
      default:
        break;
    }
  }
  return updates;
}

async function handleUpdate() {
  const id = args[0];
  if (!id) {
    console.error(
      "Usage: bun digest update <id> --title '...' --misconception '...' --content '...' --series-name '...' --series-part N"
    );
    process.exit(1);
  }

  const updates = parseUpdateFlags();
  await digests.updateOne({ _id: new ObjectId(id) }, { $set: updates });
  console.log(`Updated digest: ${id}`);
}

async function handleSchedule() {
  const id = args[0];
  const dateStr = args[1];
  if (!id) {
    console.error("Usage: bun digest schedule <id> [YYYY-MM-DDTHH:mm]");
    process.exit(1);
  }

  const scheduledFor = dateStr ? new Date(dateStr) : getNextMonday();
  await digests.updateOne(
    { _id: new ObjectId(id) },
    {
      $set: {
        scheduledFor,
        status: "scheduled",
        updatedAt: new Date(),
      },
    }
  );
  console.log(`Scheduled digest ${id} for ${scheduledFor.toISOString()}`);
}

async function handleList() {
  const allDigests = await digests.find({}).sort({ createdAt: -1 }).toArray();

  if (allDigests.length === 0) {
    console.log("No digests found.");
    return;
  }

  for (const d of allDigests) {
    const series = d.series ? ` [${d.series.name} #${d.series.part}]` : "";
    const scheduled = d.scheduledFor
      ? ` → ${d.scheduledFor.toISOString().split("T")[0]}`
      : "";
    console.log(
      `${d._id} | ${d.status.padEnd(9)} | ${d.title}${series}${scheduled}`
    );
  }
}

async function handleSend() {
  const id = args[0];
  if (!id) {
    console.error("Usage: bun digest send <id>");
    process.exit(1);
  }

  const digest = await digests.findOne({ _id: new ObjectId(id) });
  if (!digest) {
    console.error(`Digest ${id} not found`);
    process.exit(1);
  }

  if (digest.status === "sent") {
    console.error(`Digest ${id} has already been sent`);
    process.exit(1);
  }

  const { Resend } = await import("resend");
  const resend = new Resend(process.env.RESEND_TOKEN);

  const subscribers = await db
    .collection("subscribers")
    .find({ emailVerified: { $ne: null } })
    .toArray();

  if (subscribers.length === 0) {
    console.log("No verified subscribers to send to.");
    return;
  }

  console.log(`Sending to ${subscribers.length} subscribers...`);

  const html = await render(
    DigestEmail({
      content: digest.content,
      misconception: digest.misconception,
      series: digest.series,
      title: digest.title,
    })
  );

  const emails = subscribers.map((s) => s.email);
  const resendFrom = process.env.RESEND_FROM ?? "noreply@hastoggle.dev";
  const { error } = await resend.batch.send(
    emails.map((to) => ({
      from: resendFrom,
      html,
      subject: digest.title,
      to,
    }))
  );

  if (error) {
    console.error("Failed to send:", error);
    process.exit(1);
  }

  await digests.updateOne(
    { _id: new ObjectId(id) },
    {
      $set: {
        sentAt: new Date(),
        status: "sent",
        updatedAt: new Date(),
      },
    }
  );

  console.log(`Sent digest ${id} to ${subscribers.length} subscribers`);
}

function printHelp() {
  console.log("Usage: bun digest <create|update|schedule|list|send>");
  console.log("");
  console.log("Commands:");
  console.log("  create [title]                    Create a draft digest");
  console.log("  update <id> --title '...' ...     Update digest fields");
  console.log("  schedule <id> [datetime]          Schedule for sending");
  console.log("  list                              List all digests");
  console.log("  send <id>                         Send to subscribers");
}

async function main() {
  try {
    await client.connect();

    switch (command) {
      case "create":
        await handleCreate();
        break;
      case "update":
        await handleUpdate();
        break;
      case "schedule":
        await handleSchedule();
        break;
      case "list":
        await handleList();
        break;
      case "send":
        await handleSend();
        break;
      default:
        printHelp();
    }
  } finally {
    await client.close();
  }
}

function getNextMonday(): Date {
  const now = new Date();
  const day = now.getDay();
  const daysUntilMonday = day === 0 ? 1 : 8 - day;
  const nextMonday = new Date(now);
  nextMonday.setDate(now.getDate() + daysUntilMonday);
  nextMonday.setHours(9, 0, 0, 0);
  return nextMonday;
}

main();

