        width={width}
      />
      <figcaption className="mt-2 font-mono text-muted-foreground text-xs">
        A normal week. Aesop had opinions about this race — he never considered
        the turtle might employ the rabbits. The mechanism is in room III.
      </figcaption>
    </figure>
  );
}

