"""Point PROMPTS / OUTPUT_* / PromptSeed imports at ./completions instead of ./selector."""

import re
from pathlib import Path

D = Path(
    "/Users/eric/conductor/workspaces/memorynine/biarritz/apps/web/app/[locale]"
    "/learn/masterclass-28-07-2026/demos/era1-playground"
)

MOVED = {"PROMPTS", "OUTPUT_COLUMNS", "OUTPUT_LINES"}
MOVED_TYPES = {"PromptSeed"}

IMPORT_RE = re.compile(
    r'import (type )?\{([^}]*)\} from "(\.\.?/selector)";', re.S
)


def split_spec(spec):
    spec = spec.strip().rstrip(",")
    is_type = spec.startswith("type ")
    name = spec[5:].strip() if is_type else spec
    return is_type, name


for path in sorted(D.rglob("*.ts")) + sorted(D.rglob("*.tsx")):
    src = path.read_text()
    m = IMPORT_RE.search(src)
    if not m:
        continue
    blanket_type = bool(m.group(1))
    specs = [s for s in (x.strip() for x in m.group(2).split(",")) if s]
    module = m.group(3).replace("selector", "completions")

    keep, move_val, move_type = [], [], []
    for spec in specs:
        is_type, name = split_spec(spec)
        is_type = is_type or blanket_type
        if name in MOVED:
            move_val.append(name)
        elif name in MOVED_TYPES:
            move_type.append(name)
        else:
            keep.append(spec)

    if not (move_val or move_type):
        continue

    lines = []
    if keep:
        prefix = "import type " if blanket_type else "import "
        lines.append(f'{prefix}{{ {", ".join(keep)} }} from "{m.group(3)}";')
    if move_type:
        lines.append(f'import type {{ {", ".join(sorted(move_type))} }} from "{module}";')
    if move_val:
        lines.append(f'import {{ {", ".join(sorted(move_val))} }} from "{module}";')

    src = src[: m.start()] + "\n".join(lines) + src[m.end() :]
    path.write_text(src)
    print("rewrote", path.name, "->", lines)

